def ck(n,area,action,proof,fail):
 return {'id':f'A12-CK-{n:02d}','area':area,'action':action,'required_evidence':proof,'fail_condition':fail,'result':'NEEXECUTAT','evidence_ids':[],'not_applicable_requires':'Motiv particularizat la cerința taskului, dovada lipsei efectului și validarea A11; nu se acceptă gol sau N/A global.'}

checks=[
ck(1,'Inventar','Identifică taskul în exportul autoritativ P01, nu numai în Git sau într-un manual.','ID intern, cod original, titlu, URL, proiect/capitol, stare brută, data închiderii, data extragerii, hash export.','Taskul nu apare în inventarul sursă sau identitatea este reconstruită prin presupunere.'),
ck(2,'Identitate','Păstrează exact codurile originale; tratează explicit aliasuri, duplicări și coduri reutilizate.','Registru ID intern↔cod original↔alias cu motive; zero taskuri pierdute la deduplicare.','Două taskuri distincte sunt unite după titlu/cod sau o renumerotare tacită schimbă identitatea.'),
ck(3,'Cerințe','Extrage fiecare propoziție normativă, subpunct, RZ, anexă și criteriu de acceptare în cerințe atomice.','Text exact, pointer la sursă și hash; numărătoare cerințe înainte/după; dispoziția fiecărei cerințe.','Sunt auditate numai titlul, rezumatul sau o selecție convenabilă de subpuncte.'),
ck(4,'Cronologie','Separă criteriile valabile la închiderea taskului de amendamentele ulterioare aprobate.','Surse datate pentru închidere/amendament; două verdicturi: conformitate la închidere și conformitate actuală.','O cerință nouă este prezentată ca fraudă istorică ori o clarificare explicită actuală este ignorată.'),
ck(5,'Versiuni','Fixează commitul auditat, ultimul commit remote observat, versiunea nativă, buildul și versiunea instalată când accesibilă.','SHA Git, branch, fetched_at UTC, manifest build, listă bundle/feature/schema, hashuri; diferențe declarate.','HEAD local este numit ultima versiune fără comparație remote sau codul este confundat cu instalarea.'),
ck(6,'Trasabilitate','Leagă fiecare cerință de implementare și fiecare schimbare relevantă de un task ori o explicație.','Matrice cerință→fișier/simbol/linii la SHA→test→DB→pipeline→ecran; orfani expliciți.','O listă de fișiere sau commituri înlocuiește demonstrația cerinței.'),
ck(7,'Nativ iDempiere','Verifică pentru fiecare extensie dacă mecanismul există în iDempiere core, plugin instalat sau EVA.','Două căutări reproductibile: cod EVA și core la versiune; mecanism, configurație, limită, probă comparativă și justificarea diferenței.','Se declară inexistent fără corpus/versiune/căutări sau se declară nativ un plugin neconfirmat.'),
ck(8,'Frontend','Urmărește intrarea din meniul real până la rezultat: rute, taburi, formulare, validări, încărcare, gol, eroare, succes.','Inventar ecrane pe rol; capturi în mediul declarat; corespondență componentă/eveniment/endpoint; toate stările relevante.','Butonul există dar nu are backend complet, erorile se pierd sau funcția este inaccesibilă rolului necesar.'),
ck(9,'UX','Execută activitatea cu date reprezentative și măsoară reușita, pașii, mesaje, recuperare și accesibilitate.','Scenariu gestionar/contabil/vânzări/admin după task, tastatură, focus, etichete, contraste, mobil/scanner dacă aplicabil; rezultat observat.','Scorul UX este impresie estetică fără parcurs și fără recuperare după eroare.'),
ck(10,'Backend','Urmărește apelul complet prin controller/proces/serviciu/validator/model până la persistență și răspuns.','Call-chain cu simboluri și linii; precondiții, autorizare, validare server, tranzacție, erori și rezultat persistent.','Validarea este numai în UI, tranzacția este incompletă sau răspunsul succes nu corespunde datelor.'),
ck(11,'API','Compară contractul cu toate câmpurile intrate/ieșite și cu consumatorii reali.','Spec/DTO versionat, mapping complet, câmpuri obligatorii/opționale, tipuri/UOM/monedă/date, coduri eroare, paginare, compatibilitate.','Câmp comercial important este pierdut, inventat sau reinterpretat silențios.'),
ck(12,'DB/tabele','Inventariază tabelele, coloanele, cheile, indexurile, trigger-ele, view-urile și constrângerile implicate.','DDL la versiune, AD metadata, PK/FK/unique/check/nullability, tenant keys, provenance, read/write set și interogări de reconciliere.','Se verifică numai Java/JS fără efectele SQL sau se afirmă existența tabelelor fără DDL/catalog.'),
ck(13,'Migrare','Verifică ordinea și repetabilitatea migrărilor pe date existente și instanță curată.','Matrice versiune înainte/după, dependențe, preflight, backup restaurabil în mediu izolat, rollback/forward-fix și rezultate.','Migrarea corupe identități/date istorice ori rerun produce duplicări.'),
ck(14,'Izolare','Probează separarea cabinet/firma/canal/utilizator și accesul direct la API/export/atașamente.','Două firme/canale/roluri; probe permise/refuzate; context verificat pe server și la DB; același CUI în două cabinete.','URL, cod de firmă sau filtru UI ține loc de autorizare ori datele altui context sunt vizibile.'),
ck(15,'Stări','Enumeră toate tranzițiile și verifică actorul, condiția, efectul, documentul și jurnalul.','Tabel stare înainte→comandă→stare persistentă→eveniment→stare UI, inclusiv IP/WP/WC/CO unde există.','processIt(true), HTTP200 sau un toast este tratat ca finalizare contabilă/tehnică fără starea persistentă.'),
ck(16,'Pipeline','Leagă taskul de fluxurile complete, producători, consumatori și puncte de reluare.','Contract pipeline cu taskuri/zone, sursă autoritativă, corelare documente, timpi, responsabil și rezultat final verificabil.','Taskul trece izolat dar predarea către următoarea etapă pierde date, drepturi sau stare.'),
ck(17,'Concurență','Testează intercalări controlate ale cererilor care concurează pe aceeași resursă.','Barrieră/schedule reproductibil, inputuri, operații simultane, rezultate, lock/isolation/unique key și invariant înainte/după.','Doar apeluri seriale ori simpla existență a unui lock sunt prezentate ca test concurent.'),
ck(18,'Retry/idempotency','Testează dublu-click, retry rețea, mesaj duplicat, restart worker și timeout cu rezultat incert.','Cheie de idempotency cu domeniu precis, ID-uri persistente, număr efecte/documente înainte/după, reconciliere rezultat ambiguu.','Retry creează alt document/consum/încasare sau timeout produce reemitere fără reconciliere.'),
ck(19,'Erori și inversare','Testează eroare în fiecare punct cu efect și reia ori inversează controlat.','Fault injection în mediu izolat, rollback, compensare, jurnal și probe că sursa inițială rămâne urmărită.','Stocul, plata sau rezervarea este eliberată înaintea recuperării fizice/financiare necesare.'),
ck(20,'Contabilitate','Reconciliază cantități, costuri, solduri și Fact_Acct cu politica relevantă taskului.','Documente și linii contabile corelate; ecuații numerice cu semn/monedă/rotunjire; de ce poate exista/nuexista postare.','Net zero este confundat cu zero rânduri contabile, aceeași marfă/cost/manoperă este recunoscută de două ori.'),
ck(21,'Stoc și identitate','Pentru taskurile aplicabile, verifică CPP/CPA distinct, G1 unic contabil, G2 fizic și G3 alternative.','Identități imuabile, lot/ASI sau MA, locație/calitate/formă/tranzit separate; bilanț cantități și rezervări.','Aceeași marfă este multiplicată ori codul permanent este reutilizat.'),
ck(22,'Integrare externă','Verifică autentificare, mapping, timeout, rate limits, retry, ordine evenimente și reconciliere.','Contract provider/versionare, fixtures, sandbox/mocks etichetate, jurnal redactat, deduplicare și izolare per canal.','Mock este declarat probă live ori testul produce AWB/plată/publicare reală neintenționată.'),
ck(23,'Import/export','Verifică identități, tipuri, limite, duplicate, encoding, CSV/formule și reluarea lotului.','Fixturi valide/ambigue/incomplete/mari, erori per rând, totaluri și query reconciliere fără date sensibile inutile.','Importul alege arbitrar produsul/ASI, pierde câmpuri ori poate traversa contextul firmei.'),
ck(24,'Configurare','Verifică fiecare setare: locație UI, default, domeniu, validare, efect, dependențe și modificare în timp.','Catalog setare→task→schemă→UI→validator→test; configurare invalidă refuzată pe server.','Setări incompatibile pot activa un flux incomplet sau defaultul schimbă documente istorice.'),
ck(25,'Performanță','Testează volume reprezentative, interogări, paginare, concurență, cache și limite de resurse.','Dataset definit, plan SQL, număr queryuri, măsurători percentile/buget agreat, expirare/izolare cache.','Se prezintă viteză pe câteva rânduri drept capacitate de producție sau lipsesc numitorii.'),
ck(26,'Securitate aplicație','Verifică validarea inputului, injecții, XSS, CSRF, acces la fișiere, secrete și loguri pentru suprafața taskului.','Callsite și probe neintruzive în mediu autorizat; date de test, fără afișare tokenuri/secrete.','Secretele ori datele altor firme sunt expuse, intrările neîncredere sunt executate.'),
ck(27,'Operare','Verifică observabilitatea, alertarea, recovery și responsabilul după eșec.','Correlation ID, audit trail, loguri redactate, metrice, dead-letter/replay, runbook și demonstrație de recuperare.','Operatorul vede succes fals sau nu poate identifica/repara o operație întreruptă.'),
ck(28,'Build și instalare','Verifică includerea în build/pachet, dependențe, teste CI și configurație de activare.','Rezultat build/test reproductibil, manifest artifact, versiune bundle și compatibilitate; smoke în mediul declarat.','Codul neîmpachetat/neinstalat este declarat funcțional în producție.'),
ck(29,'Regresii','Verifică funcțiile native/EVA vecine și efectele taskului în celelalte capitole.','Impact map, teste pentru consumatorii contractului și controlul meniurilor/rolurilor existente.','Noua funcție ascunde sau rupe funcții contabile ori dublează serviciul comun.'),
ck(30,'Dovezi','Verifică integritatea și reproducibilitatea fiecărei dovezi și a rezultatului așteptat.','Fișier/hash, comandă sau pași, mediu, timp UTC, input, expected, observed, verdict, redacții; fără placeholder în raport final.','Dovada este numai afirmația agentului, screenshot generic sau path care nu mai există.'),
ck(31,'Constatări','Pentru fiecare defect, probează cauza, impactul, aria și reproducerea; verifică posibile contraexemple.','Pași minimali, evidence IDs, gravitate justificată, afectare, remediere recomandată, test regresie, cross-zone dedup.','Raportul prezintă suspiciune ca defect confirmat, ignoră configurarea nativă sau dublează același defect.'),
ck(32,'Acoperire','Reconciliază toate cerințele și scenariile aplicabile cu rezultatele, inclusiv cele blocate.','Numitori: total taskuri finalizate, cerințe, scenarii, dovezi, rapoarte revizuite; zero orfani; excluderi explicite.','Se raportează 100% din cele executate ascunzând cele neexecutate sau taskuri neinventariate.'),
ck(33,'Autocontrol','Execută checklistul propriu înainte de predare, verificând semantic toate câmpurile și dovezile.','Jurnal auto-QA, validare schema, linkuri, numere, consistența verdictului și control pe cel puțin o reproducere per finding.','Completarea automată a câmpurilor ori o numărătoare de rânduri ține loc de lectură tehnică.'),
ck(34,'Audit independent','Predă raportul complet și probele A11; răspunde punctual și reexecută probele cerute.','Review A11 separat, itemuri acceptate/respinse, runde de reaudits cu hash raport/dovezi și scor justificat.','Autorul își acordă singur 10/10 ori se schimbă raportul după review fără reverificare.'),
ck(35,'Versiune la închidere','Recompară SHA remote și starea taskului față de snapshotul inițial; tratează delta.','Manifest final, taskuri noi/reîncadrate/redeschise, fișiere schimbate și teste invalide/refăcute.','Un raport vechi este prezentat ca audit al ultimei versiuni după schimbarea codului sau criteriilor.'),
ck(36,'Verdict onest','Separă calitatea auditului de conformitatea implementării și de disponibilitatea probelor.','Scor A11, verdict implementare, acoperire executată, blocaje rămase, concluzie cu domeniu/versiune exactă.','10/10 este interpretat ca software fără defecte ori un NEEXECUTAT este convertit în PASS.')]

